  if (!partes.length) return { ok: false, motivo: 'llm_vazio' };
  if (partes.length > ACQ07_MAX_PARTES) partes = partes.slice(0, ACQ07_MAX_PARTES - 1).concat([partes.slice(ACQ07_MAX_PARTES - 1).join(' ')]);
  var texto = partes.join('\n');
