  if (h.indexOf('sha256=') !== 0) return { ok: false, motivo: 'sem_assinatura' };
  return acqIguaisSeguro(h.slice(7).toLowerCase(), acqHmacSha256(appSecret, corpoBruto)) ? { ok: true } : { ok: false, motivo: 'assinatura_invalida' };
}

